export const fetchUserLikesForPictures = async (userId: string, pictureIds: string[], client?: SupabaseClient) => {
    const supabase = client || defaultSupabase;
    if (pictureIds.length === 0) return [];

    // Create a deterministic cache key. Max length consideration might be needed for very large posts,
    // but for now simple join is fine or we can skip cache for very large sets.
    const sortedIds = [...pictureIds].sort();
    // Using a hash or truncated key might be safer for URL limits if this was GET, but internal map is fine.
    const key = `likes-batch-${userId}-${sortedIds.slice(0, 5).join(',')}-${sortedIds.length}`;

    return fetchWithDeduplication(key, async () => {
        const { data, error } = await supabase
            .from('likes')
            .select('picture_id')
            .eq('user_id', userId)
            .in('picture_id', pictureIds);

        if (error) throw error;
        // Return array of liked picture IDs
        return data.map(like => like.picture_id);
    });
};

export interface FeedPost {
    id: string; // Post ID
    title: string;
    description: string | null;
    created_at: string;
    user_id: string;
    pictures: MediaItem[]; // All visible pictures
    cover: MediaItem; // The selected cover picture
    likes_count: number;
    comments_count: number;
    type: MediaType;
    author_profile?: UserProfile;
}

export const fetchFeedPosts = async (
    source: 'home' | 'collection' | 'tag' | 'user' = 'home',
    sourceId?: string,
    isOrgContext?: boolean,
    orgSlug?: string,
    client?: SupabaseClient
): Promise<FeedPost[]> => {
    // Forward to paginated version with defaults
    return fetchFeedPostsPaginated(source, sourceId, isOrgContext, orgSlug, 0, 30, client);
};

export const fetchFeedPostsPaginated = async (
    source: 'home' | 'collection' | 'tag' | 'user' = 'home',
    sourceId?: string,
    isOrgContext?: boolean,
    orgSlug?: string,
    page: number = 0,
    pageSize: number = 30,
    client?: SupabaseClient
): Promise<FeedPost[]> => {
    const supabase = client || defaultSupabase;
    const start = page * pageSize;
    const end = start + pageSize - 1;

    // 1. Fetch Posts
    let query = supabase
        .from('posts')
        .select(`
            *,
            pictures(
                id,
                image_url,
                thumbnail_url,
                type,
                meta,
                description,
                likes_count,
                visible,
                is_selected,
                position,
                parent_id,
                created_at,
                title
            )
        `)
        .order('created_at', { ascending: false })
        .range(start, end);

    // Filter out non-public posts (listed/private) for the home feed
    if (!sourceId && source === 'home') {
        query = query.or('settings.is.null,settings->>visibility.eq.public');
    }

    // Org context logic (placeholder from PhotoGrid)
    if (isOrgContext && orgSlug) {
        /*
        const { data: org } = await supabase
            .from('organizations')
            .select('id')
            .eq('slug', orgSlug)
            .single();
            */
    }

    const { data: postsData, error: postsError } = await query;
    if (postsError) throw postsError;

    // 2. Fetch Pages (if applicable)
    // Only fetch pages for home/user/org sources to keep it simple for now
    let pagesData: any[] = [];
    if (source === 'home' || source === 'user' || source === 'collection') {
        let pageQuery = supabase
            .from('pages')
            .select('*')
            .order('created_at', { ascending: false })
            .range(start, end);

        if (source === 'user' && sourceId) {
            pageQuery = pageQuery.eq('owner', sourceId);
            // If viewing someone else's profile, usually only public pages
            // But let's assume if sourceId is provided we might want to filter visibility
            // For now, let's fetch all public ones if not owner? 
            // Logic in PageManager was: if (!isOwnProfile) eq('is_public', true).eq('visible', true)
            // We'll mimic strict visibility for feed:
            pageQuery = pageQuery.eq('is_public', true).eq('visible', true);
        } else if (source === 'home') {
            pageQuery = pageQuery.eq('is_public', true).eq('visible', true);
        }

        const { data: pages, error: pagesError } = await pageQuery;

        if (!pagesError && pages) {
            pagesData = pages;
        }
        console.log('pagesData : source', source, pagesData);
    } else {
        console.log('no pages for source', source);
    }

    // 2.5 Extract Page Images
    const pageImageIds: string[] = [];
    const pageIdToImageId = new Map<string, string>();
    pagesData.forEach(page => {
        let content = page.content;
        if (typeof content === 'string') {
            try {
                content = JSON.parse(content);
            } catch (e) {
                console.error(`[db] Failed to parse content for page ${page.id}`, e);
                return;
            }
        }

        // Handle new structure: { pages: { [pageId]: { containers: [] } } }
        let containers = content?.containers;

        if (!containers && content?.pages) {
            // Find the first page in the dictionary
            const firstPageKey = Object.keys(content.pages)[0];
            if (firstPageKey && content.pages[firstPageKey]?.containers) {
                containers = content.pages[firstPageKey].containers;
                // console.log(`[db] Found containers in nested page ${firstPageKey}`);
            }
        }

        if (!containers) {

            return;
        }

        // Find first photo-card
        for (const container of containers) {
            if (container.widgets) {
                const photoWidget = container.widgets.find((w: any) => w.widgetId === 'photo-card' && w.props?.pictureId);
                if (photoWidget) {
                    const picId = photoWidget.props.pictureId;

                    pageImageIds.push(picId);
                    pageIdToImageId.set(page.id, picId);
                    break; // Found first image for this page
                }
            }
        }
    });

    const pageImages = new Map<string, string>();
    if (pageImageIds.length > 0) {
        const { data: pics } = await supabase
            .from('pictures')
            .select('id, image_url')
            .in('id', pageImageIds);

        pics?.forEach(p => pageImages.set(p.id, p.image_url));
    }

    // 3. Process Posts (existing logic)
    const rootIds = new Set<string>();
    const postCandidates = new Map<string, any>();

    (postsData as any[] || []).forEach((post) => {
        const pics = post.pictures as any[] || [];
        const validPics = pics.filter(p => p.visible !== false);
        validPics.sort((a, b) => (a.position || 0) - (b.position || 0));

        const cover = validPics[0];
        if (cover) {
            postCandidates.set(post.id, cover);
            rootIds.add(cover.parent_id || cover.id);
        }
    });

    // 4. Fetch overrides
    let selectedVersions: any[] = [];
    if (rootIds.size > 0) {
        selectedVersions = await fetchSelectedVersions(Array.from(rootIds), supabase); // Pass supabase client
    }

    // 5. Transform Posts
    const transformedPosts: FeedPost[] = (postsData as any[] || [])
        .map((post) => {
            let coverPic = postCandidates.get(post.id);

            // Handle Link Posts (no pictures but has link settings)
            if (!coverPic) {
                const settings = (post.settings as any) || {};
                if (settings && settings.link) {
                    // Create virtual picture for link post
                    coverPic = {
                        id: post.id,
                        picture_id: post.id,
                        title: post.title,
                        description: post.description,
                        image_url: settings.image_url || 'https://picsum.photos/seed/' + post.id + '/600/400', // Fallback or use settings image
                        thumbnail_url: settings.thumbnail_url || null,
                        type: 'page-external',
                        meta: { url: settings.link },
                        created_at: post.created_at,
                        user_id: post.user_id,
                        likes_count: 0,
                        comments: [{ count: 0 }],
                        visible: true,
                        is_selected: false,
                        position: 0
                    };
                } else {
                    return null;
                }
            }

            const rootId = coverPic.parent_id || coverPic.id;
            const selected = selectedVersions?.find((v: any) =>
                (v.id === rootId || v.parent_id === rootId) && v.is_selected
            );

            if (selected && selected.id !== coverPic.id) {
                coverPic = selected;
            }

            const pics = post.pictures as any[] || [];
            const validPics = pics.filter(p => p.visible !== false)
                .sort((a, b) => (a.position || 0) - (b.position || 0));

            return {
                id: post.id,
                title: post.title,
                description: post.description,
                created_at: post.created_at,
                user_id: post.user_id,
                pictures: validPics,
                cover: coverPic,
                likes_count: validPics.reduce((sum, p) => sum + (p.likes_count || 0), 0),
                comments_count: 0,
                type: coverPic.type as MediaType,
            };
        })
        .filter((item) => item !== null) as FeedPost[];

    // 6. Transform Pages
    // We treat Pages as FeedPosts with a single "virtual" picture of type 'page-intern'
    const transformedPages: FeedPost[] = pagesData.map(page => {
        // Resolve mage
        let displayImage = "https://picsum.photos/640"; // Fallback
        const requiredPicId = pageIdToImageId.get(page.id);
        if (requiredPicId) {
            const foundUrl = pageImages.get(requiredPicId);
            if (foundUrl) displayImage = foundUrl;
        }


        // Virtual picture for the page
        const virtualPic: any = {
            id: page.id, // Use page ID as picture ID in grid context? Or make a virtual one? 
            // Using page ID is risky if IDs collide, but UUIDs shouldn't.
            image_url: displayImage,
            thumbnail_url: null,
            type: 'page-intern',
            meta: { slug: page.slug }, // Store slug in meta for easy access
            description: null,
            likes_count: 0,
            visible: true,
            is_selected: false,
            position: 0,
            created_at: page.created_at,
            title: page.title
        };

        return {
            id: page.id,
            title: page.title,
            description: null, // Could parse content?
            created_at: page.created_at,
            user_id: page.owner,
            pictures: [virtualPic],
            cover: virtualPic,
            likes_count: 0,
            comments_count: 0,
            type: 'page-intern' as MediaType,
        };
    });

    // 7. Merge and Sort
    const allItems = [...transformedPosts, ...transformedPages];
    allItems.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());

    return allItems;
};

// Map FeedPost[] back to MediaItemType[] for backward compatibility w/ PhotoGrid
export const mapFeedPostsToMediaItems = (posts: FeedPost[], sortBy: 'latest' | 'top' = 'latest'): any[] => {
    return posts.map(post => {
        let cover = post.cover;

        // Select cover based on sort mode
        if (post.pictures && post.pictures.length > 0) {
            const validPics = post.pictures.filter((p: any) => p.visible !== false);

            if (validPics.length > 0) {
                if (sortBy === 'latest') {
                    // For "Latest" mode: Show the newest picture (by created_at)
                    cover = validPics.reduce((newest, current) => {
                        const newestDate = new Date(newest.created_at || post.created_at).getTime();
                        const currentDate = new Date(current.created_at || post.created_at).getTime();
                        return currentDate > newestDate ? current : newest;
                    });
                } else {
                    // For "Top" or default: Use first by position (existing behavior)
                    const sortedByPosition = [...validPics].sort((a, b) => (a.position || 0) - (b.position || 0));
                    cover = sortedByPosition[0];
                }
            } else {
                cover = post.pictures[0]; // Fallback to any picture
            }
        }

        if (!cover) return null;
        return {
            id: post.id,
            picture_id: cover.id,
            title: post.title,
            description: post.description,
            image_url: cover.image_url,
            thumbnail_url: cover.thumbnail_url,
            type: cover.type as MediaType,
            meta: cover.meta,
            created_at: post.created_at,
            user_id: post.user_id,
            likes_count: post.likes_count,
            comments: [{ count: post.comments_count }],
            responsive: (cover as any).responsive,
            job: (cover as any).job,
            // author_profile must be populated externally
        };
    }).filter(item => item !== null);
};

// Augment posts if they come from API/Hydration (missing cover/author_profile)
export const augmentFeedPosts = (posts: any[]): FeedPost[] => {
    return posts.map(p => {
        // Check if we need to augment (heuristic: missing cover)
        if (!p.cover) {
            const pics = p.pictures || [];
            const validPics = pics.filter((pic: any) => pic.visible !== false)
                .sort((a: any, b: any) => (a.position || 0) - (b.position || 0));

            return {
                ...p,
                cover: validPics[0] || pics[0], // fallback to first if none visible?
                author_profile: p.author ? {
                    user_id: p.author.user_id,
                    username: p.author.username,
                    display_name: p.author.display_name,
                    avatar_url: p.author.avatar_url
                } : undefined
            };
        }
        return p;
    });
};
