/**
 * usePostNavigation Hook
 * 
 * Compatibility wrapper around Zustand navigationStore
 * Provides same API as old PostNavigationContext for easy migration
 */

import { useNavigationStore, selectNavigationData } from '@/stores/navigationStore';

export const usePostNavigation = () => {
  const navigationData = useNavigationStore(selectNavigationData);
  const setNavigationData = useNavigationStore((state) => state.setNavigationData);
  const preloadImage = useNavigationStore((state) => state.preloadImage);
  const updateCurrentIndex = useNavigationStore((state) => state.updateCurrentIndex);

  return {
    navigationData,
    setNavigationData,
    preloadImage,
    updateCurrentIndex,
  };
};

// Export for backward compatibility
export default usePostNavigation;

